B.asI=new A.mX("\u041a\u0430\u043a \u044d\u0442\u043e \u0440\u0430\u0431\u043e\u0442\u0430\u0435\u0442","\u041a\u0430\u043a \u044d\u0442\u043e \u0440\u0430\u0431\u043e\u0442\u0430\u0435\u0442\n\nCOSMOS \u043e\u043f\u0438\u0441\u044b\u0432\u0430\u0435\u0442 \u0445\u0430\u0440\u0430\u043a\u0442\u0435\u0440 \u043f\u043e \u0434\u0430\u0442\u0435 \u0440\u043e\u0436\u0434\u0435\u043d\u0438\u044f \u043f\u043e \u0441\u0438\u0441\u0442\u0435\u043c\u0435 \u041e\u043d\u0442\u043e\u043b\u043e\u0433\u0438\u044f. \u0418\u0437 \u0446\u0438\u0444\u0440 \u0434\u0430\u0442\u044b \u043f\u043e\u043b\u0443\u0447\u0430\u044e\u0442\u0441\u044f \u043d\u0435\u0441\u043a\u043e\u043b\u044c\u043a\u043e \u0447\u0438\u0441\u0435\u043b \u043e\u0442 1 \u0434\u043e 9 \u2014 \u0443 \u043a\u0430\u0436\u0434\u043e\u0433\u043e \u0441\u0432\u043e\u044f \u0440\u043e\u043b\u044c: 1 \u041b\u0438\u0434\u0435\u0440, 2 \u0414\u0438\u043f\u043b\u043e\u043c\u0430\u0442, 3 \u041d\u0430\u0441\u0442\u0430\u0432\u043d\u0438\u043a, 4 \u041d\u043e\u0432\u0430\u0442\u043e\u0440, 5 \u041a\u043e\u043c\u043c\u0443\u043d\u0438\u043a\u0430\u0442\u043e\u0440, 6 \u042d\u0441\u0442\u0435\u0442, 7 \u0418\u0441\u0441\u043b\u0435\u0434\u043e\u0432\u0430\u0442\u0435\u043b\u044c, 8 \u0421\u0442\u0440\u0430\u0442\u0435\u0433, 9 \u0411\u043e\u0435\u0446.\n\n\u0427\u0438\u0441\u043b\u043e \u0414\u0443\u0448\u0438 \u2014 \u0434\u0435\u043d\u044c \u0440\u043e\u0436\u0434\u0435\u043d\u0438\u044f, \u0441\u0432\u0435\u0434\u0451\u043d\u043d\u044b\u0439 \u043a \u043e\u0434\u043d\u043e\u0439 \u0446\u0438\u0444\u0440\u0435 (14 \u2192 1+4 = 5). \u041f\u043e\u043a\u0430\u0437\u044b\u0432\u0430\u0435\u0442, \u043a\u0430\u043a \u0432\u044b \u0443\u0441\u0442\u0440\u043e\u0435\u043d\u044b \u0432\u043d\u0443\u0442\u0440\u0438: \u0447\u0442\u043e \u0434\u0430\u0451\u0442 \u0441\u0438\u043b\u044b, \u0447\u0442\u043e \u0432\u044b\u0431\u0438\u0432\u0430\u0435\u0442 \u0438\u0437 \u043a\u043e\u043b\u0435\u0438 \u0438 \u043a\u0430\u043a \u0432\u044b \u0440\u0435\u0430\u0433\u0438\u0440\u0443\u0435\u0442\u0435 \u043d\u0430 \u043b\u044e\u0434\u0435\u0439 \u0438 \u0441\u043e\u0431\u044b\u0442\u0438\u044f.\n\n\u0427\u0438\u0441\u043b\u043e \u0421\u0443\u0434\u044c\u0431\u044b \u2014 \u0441\u0443\u043c\u043c\u0430 \u0432\u0441\u0435\u0445 \u0446\u0438\u0444\u0440 \u0434\u0430\u0442\u044b \u0440\u043e\u0436\u0434\u0435\u043d\u0438\u044f, \u0441\u0432\u0435\u0434\u0451\u043d\u043d\u0430\u044f \u043a \u043e\u0434\u043d\u043e\u0439 \u0446\u0438\u0444\u0440\u0435 (14.04.1987 \u2192 34 \u2192 7). \u041f\u043e\u043a\u0430\u0437\u044b\u0432\u0430\u0435\u0442, \u0447\u0435\u043c\u0443 \u0432\u0430\u0441 \u0443\u0447\u0438\u0442 \u0436\u0438\u0437\u043d\u044c \u0438 \u0433\u0434\u0435 \u0432\u0430\u0448 \u0433\u043b\u0430\u0432\u043d\u044b\u0439 \u0440\u043e\u0441\u0442.\n\n\u0421\u043e\u0447\u0435\u0442\u0430\u043d\u0438\u0435 \u0414\u0443\u0448\u0438 \u0438 \u0421\u0443\u0434\u044c\u0431\u044b \u2014 81 \u0432\u0430\u0440\u0438\u0430\u043d\u0442. \u041e\u043d\u043e \u043e\u0431\u044a\u044f\u0441\u043d\u044f\u0435\u0442 \u0432\u0430\u0448 \u0433\u043b\u0430\u0432\u043d\u044b\u0439 \u0432\u043d\u0443\u0442\u0440\u0435\u043d\u043d\u0438\u0439 \u043a\u043e\u043d\u0444\u043b\u0438\u043a\u0442: \u0447\u0442\u043e \u0432\u0430\u043c \u0445\u043e\u0447\u0435\u0442\u0441\u044f \u043f\u043e \u043d\u0430\u0442\u0443\u0440\u0435 \u0438 \u043a\u0443\u0434\u0430 \u043f\u0440\u0438 \u044d\u0442\u043e\u043c \u0432\u0435\u0434\u0451\u0442 \u0436\u0438\u0437\u043d\u044c.\n\n\u0427\u0438\u0441\u043b\u043e \u0433\u043e\u0434\u0430, \u043c\u0435\u0441\u044f\u0446\u0430 \u0438 \u0434\u043d\u044f \u2014 \u0442\u043e\u043d \u0442\u0435\u043a\u0443\u0449\u0435\u0433\u043e \u043f\u0435\u0440\u0438\u043e\u0434\u0430. \u0413\u043e\u0434 \u0441\u0447\u0438\u0442\u0430\u0435\u0442\u0441\u044f \u0438\u0437 \u0434\u043d\u044f \u0438 \u043c\u0435\u0441\u044f\u0446\u0430 \u0440\u043e\u0436\u0434\u0435\u043d\u0438\u044f \u043f\u043b\u044e\u0441 \u0442\u0435\u043a\u0443\u0449\u0438\u0439 \u0433\u043e\u0434, \u043c\u0435\u0441\u044f\u0446 \u0438 \u0434\u0435\u043d\u044c \u2014 \u043e\u0442 \u043d\u0435\u0433\u043e. \u042d\u0442\u043e \u043f\u043e\u0434\u0441\u043a\u0430\u0437\u043a\u0430, \u043a\u0430\u043a\u0438\u0435 \u0432\u0430\u0448\u0438 \u043a\u0430\u0447\u0435\u0441\u0442\u0432\u0430 \u0441\u0435\u0439\u0447\u0430\u0441 \u0440\u0430\u0431\u043e\u0442\u0430\u044e\u0442 \u043b\u0443\u0447\u0448\u0435 \u0432\u0441\u0435\u0433\u043e.\n\n\xab\u0412 \u043f\u043b\u044e\u0441\u0435\xbb \u0438 \xab\u0432 \u043c\u0438\u043d\u0443\u0441\u0435\xbb \u2014 \u0434\u0432\u0430 \u0441\u043e\u0441\u0442\u043e\u044f\u043d\u0438\u044f \u043a\u0430\u0436\u0434\u043e\u0433\u043e \u0447\u0438\u0441\u043b\u0430. \u0412 \u043f\u043b\u044e\u0441\u0435 \u0432\u044b \u0432 \u0440\u0435\u0441\u0443\u0440\u0441\u0435: \u0441\u043e\u0431\u0440\u0430\u043d\u044b, \u0440\u0430\u0441\u0442\u0451\u0442\u0435, \u0432\u0430\u0448\u0438 \u0441\u0438\u043b\u044c\u043d\u044b\u0435 \u0441\u0442\u043e\u0440\u043e\u043d\u044b \u0440\u0430\u0431\u043e\u0442\u0430\u044e\u0442. \u0412 \u043c\u0438\u043d\u0443\u0441\u0435 \u2014 \u0443\u0441\u0442\u0430\u043b\u0438 \u0438\u043b\u0438 \u0437\u0430\u0434\u0435\u0442\u044b: \u043e\u0431\u0438\u0434\u044b, \u043f\u0440\u0435\u0442\u0435\u043d\u0437\u0438\u0438, \u043a\u043e\u043d\u0442\u0440\u043e\u043b\u044c, \u0441\u0440\u044b\u0432\u044b. \u0420\u0430\u0437\u0431\u043e\u0440 \u043f\u043e\u0434\u0441\u043a\u0430\u0437\u044b\u0432\u0430\u0435\u0442, \u043a\u0430\u043a \u0432\u043e\u0437\u0432\u0440\u0430\u0449\u0430\u0442\u044c\u0441\u044f \u0432 \u043f\u043b\u044e\u0441.\n\n\u0422\u0435\u043a\u0441\u0442\u044b \u0441\u043e\u0441\u0442\u0430\u0432\u043b\u044f\u0435\u0442 \u0438\u0441\u043a\u0443\u0441\u0441\u0442\u0432\u0435\u043d\u043d\u044b\u0439 \u0438\u043d\u0442\u0435\u043b\u043b\u0435\u043a\u0442 \u043d\u0430 \u043e\u0441\u043d\u043e\u0432\u0435 \u044d\u0442\u0438\u0445 \u043f\u0440\u0430\u0432\u0438\u043b. \u042d\u0442\u043e \u0438\u043d\u0441\u0442\u0440\u0443\u043c\u0435\u043d\u0442 \u0434\u043b\u044f \u0441\u0430\u043c\u043e\u043f\u043e\u0437\u043d\u0430\u043d\u0438\u044f, \u0430 \u043d\u0435 \u043f\u0440\u0435\u0434\u0441\u043a\u0430\u0437\u0430\u043d\u0438\u0435 \u0431\u0443\u0434\u0443\u0449\u0435\u0433\u043e.",null)
B.asJ=new A.mX("\u0423\u0441\u043b\u043e\u0432\u0438\u044f","\u0423\u0441\u043b\u043e\u0432\u0438\u044f \u0438\u0441\u043f\u043e\u043b\u044c\u0437\u043e\u0432\u0430\u043d\u0438\u044f COSMOS\n\n1. COSMOS \u2014 \u043f\u0440\u0438\u043b\u043e\u0436\u0435\u043d\u0438\u0435 \u0434\u043b\u044f \u0441\u0430\u043c\u043e\u043f\u043e\u0437\u043d\u0430\u043d\u0438\u044f \u043d\u0430 \u043e\u0441\u043d\u043e\u0432\u0435 \u0441\u0438\u0441\u0442\u0435\u043c\u044b \u041e\u043d\u0442\u043e\u043b\u043e\u0433\u0438\u044f (\u0422\u0435\u043d\u0433\u0440\u0438\u0430\u043d\u0441\u0442\u0432\u043e). \u0420\u0430\u0437\u0431\u043e\u0440\u044b \u043d\u043e\u0441\u044f\u0442 \u0438\u043d\u0444\u043e\u0440\u043c\u0430\u0446\u0438\u043e\u043d\u043d\u044b\u0439 \u0438 \u0440\u0430\u0437\u0432\u043b\u0435\u043a\u0430\u0442\u0435\u043b\u044c\u043d\u044b\u0439 \u0445\u0430\u0440\u0430\u043a\u0442\u0435\u0440.\n\n2. \u0420\u0430\u0437\u0431\u043e\u0440\u044b \u043d\u0435 \u044f\u0432\u043b\u044f\u044e\u0442\u0441\u044f \u043c\u0435\u0434\u0438\u0446\u0438\u043d\u0441\u043a\u043e\u0439, \u043f\u0441\u0438\u0445\u043e\u043b\u043e\u0433\u0438\u0447\u0435\u0441\u043a\u043e\u0439, \u044e\u0440\u0438\u0434\u0438\u0447\u0435\u0441\u043a\u043e\u0439 \u0438\u043b\u0438 \u0444\u0438\u043d\u0430\u043d\u0441\u043e\u0432\u043e\u0439 \u043a\u043e\u043d\u0441\u0443\u043b\u044c\u0442\u0430\u0446\u0438\u0435\u0439. \u041d\u0435 \u043f\u0440\u0438\u043d\u0438\u043c\u0430\u0439\u0442\u0435 \u0440\u0435\u0448\u0435\u043d\u0438\u0439 \u043e \u0437\u0434\u043e\u0440\u043e\u0432\u044c\u0435, \u043b\u0435\u0447\u0435\u043d\u0438\u0438, \u0434\u0435\u043d\u044c\u0433\u0430\u0445 \u0438\u043b\u0438 \u043e\u0442\u043d\u043e\u0448\u0435\u043d\u0438\u044f\u0445 \u0442\u043e\u043b\u044c\u043a\u043e \u043d\u0430 \u043e\u0441\u043d\u043e\u0432\u0430\u043d\u0438\u0438 \u0440\u0430\u0437\u0431\u043e\u0440\u0430. \u041f\u0440\u0438 \u043f\u0440\u043e\u0431\u043b\u0435\u043c\u0430\u0445 \u0441\u043e \u0437\u0434\u043e\u0440\u043e\u0432\u044c\u0435\u043c \u043e\u0431\u0440\u0430\u0442\u0438\u0442\u0435\u0441\u044c \u043a \u0432\u0440\u0430\u0447\u0443.\n\n3. \u0422\u0435\u043a\u0441\u0442\u044b \u0433\u0435\u043d\u0435\u0440\u0438\u0440\u0443\u044e\u0442\u0441\u044f \u0438\u0441\u043a\u0443\u0441\u0441\u0442\u0432\u0435\u043d\u043d\u044b\u043c \u0438\u043d\u0442\u0435\u043b\u043b\u0435\u043a\u0442\u043e\u043c \u0438 \u043c\u043e\u0433\u0443\u0442 \u0441\u043e\u0434\u0435\u0440\u0436\u0430\u0442\u044c \u043d\u0435\u0442\u043e\u0447\u043d\u043e\u0441\u0442\u0438.\n\n4. \u041f\u043b\u0430\u0442\u043d\u044b\u0435 \u0440\u0430\u0437\u0431\u043e\u0440\u044b \u2014 \u0440\u0430\u0437\u043e\u0432\u044b\u0435 \u043f\u043e\u043a\u0443\u043f\u043a\u0438 \u0447\u0435\u0440\u0435\u0437 Google Play \u0438\u043b\u0438 App Store. \u041a\u0430\u0436\u0434\u0430\u044f \u043f\u043e\u043a\u0443\u043f\u043a\u0430 \u043e\u0442\u043a\u0440\u044b\u0432\u0430\u0435\u0442 \u043e\u0434\u0438\u043d \u043f\u043e\u043b\u043d\u044b\u0439 \u0440\u0430\u0437\u0431\u043e\u0440 \u0434\u043b\u044f \u043e\u0434\u043d\u043e\u0439 \u0434\u0430\u0442\u044b \u0440\u043e\u0436\u0434\u0435\u043d\u0438\u044f \u0438\u043b\u0438 \u043e\u0434\u0438\u043d \u0430\u043d\u0430\u043b\u0438\u0437 \u0434\u043b\u044f \u043e\u0434\u043d\u043e\u0439 \u043f\u0430\u0440\u044b. \u0412\u043e\u0437\u0432\u0440\u0430\u0442\u044b \u2014 \u043f\u043e \u043f\u0440\u0430\u0432\u0438\u043b\u0430\u043c \u043c\u0430\u0433\u0430\u0437\u0438\u043d\u0430 \u043f\u0440\u0438\u043b\u043e\u0436\u0435\u043d\u0438\u0439.\n\n5. \u041a\u0443\u043f\u043b\u0435\u043d\u043d\u044b\u0435 \u0440\u0430\u0437\u0431\u043e\u0440\u044b \u0445\u0440\u0430\u043d\u044f\u0442\u0441\u044f \u0442\u043e\u043b\u044c\u043a\u043e \u043d\u0430 \u0443\u0441\u0442\u0440\u043e\u0439\u0441\u0442\u0432\u0435: \u0432 COSMOS \u043d\u0435\u0442 \u0430\u043a\u043a\u0430\u0443\u043d\u0442\u043e\u0432. \u041f\u0440\u0438 \u0443\u0434\u0430\u043b\u0435\u043d\u0438\u0438 \u043f\u0440\u0438\u043b\u043e\u0436\u0435\u043d\u0438\u044f \u0438\u043b\u0438 \u0435\u0433\u043e \u0434\u0430\u043d\u043d\u044b\u0445 \u043e\u043d\u0438 \u0443\u0434\u0430\u043b\u044f\u044e\u0442\u0441\u044f, \u0438 \u0432\u0435\u0440\u043d\u0443\u0442\u044c \u0438\u0445 \u0431\u0435\u0437 \u043d\u043e\u0432\u043e\u0439 \u043f\u043e\u043a\u0443\u043f\u043a\u0438 \u043d\u0435\u043b\u044c\u0437\u044f.\n\n6. \u041f\u043e\u0434\u043f\u0438\u0441\u043a\u0430 COSMOS Plus \u043e\u0442\u043a\u0440\u044b\u0432\u0430\u0435\u0442 \u043f\u043e\u043b\u043d\u044b\u0435 \u0440\u0430\u0437\u0431\u043e\u0440\u044b \u0438 \u0441\u043e\u0432\u043c\u0435\u0441\u0442\u0438\u043c\u043e\u0441\u0442\u044c \u0434\u043b\u044f \u043b\u044e\u0431\u044b\u0445 \u0434\u0430\u0442 \u0438 \u0434\u0430\u0451\u0442 \u0431\u043e\u043b\u044c\u0448\u0435 \u0432\u043e\u043f\u0440\u043e\u0441\u043e\u0432 \u0432 \u0447\u0430\u0442\u0435. \u0426\u0435\u043d\u0430 \u0438 \u043f\u0435\u0440\u0438\u043e\u0434 (\u043c\u0435\u0441\u044f\u0446 \u0438\u043b\u0438 \u0433\u043e\u0434) \u043f\u043e\u043a\u0430\u0437\u044b\u0432\u0430\u044e\u0442\u0441\u044f \u0434\u043e \u043e\u043f\u043b\u0430\u0442\u044b. \u041f\u043e\u0434\u043f\u0438\u0441\u043a\u0430 \u043f\u0440\u043e\u0434\u043b\u0435\u0432\u0430\u0435\u0442\u0441\u044f \u0430\u0432\u0442\u043e\u043c\u0430\u0442\u0438\u0447\u0435\u0441\u043a\u0438, \u043f\u043e\u043a\u0430 \u0432\u044b \u0435\u0451 \u043d\u0435 \u043e\u0442\u043c\u0435\u043d\u0438\u0442\u0435; \u043e\u0442\u043c\u0435\u043d\u0438\u0442\u044c \u043c\u043e\u0436\u043d\u043e \u0432 \u043b\u044e\u0431\u043e\u0439 \u043c\u043e\u043c\u0435\u043d\u0442 \u0432 Google Play \u2192 \xab\u041f\u043b\u0430\u0442\u0435\u0436\u0438 \u0438 \u043f\u043e\u0434\u043f\u0438\u0441\u043a\u0438\xbb \u2192 \xab\u041f\u043e\u0434\u043f\u0438\u0441\u043a\u0438\xbb, \u0434\u043e\u0441\u0442\u0443\u043f \u0441\u043e\u0445\u0440\u0430\u043d\u044f\u0435\u0442\u0441\u044f \u0434\u043e \u043a\u043e\u043d\u0446\u0430 \u043e\u043f\u043b\u0430\u0447\u0435\u043d\u043d\u043e\u0433\u043e \u043f\u0435\u0440\u0438\u043e\u0434\u0430. \u0415\u0441\u043b\u0438 \u043f\u0440\u0435\u0434\u043b\u043e\u0436\u0435\u043d \u0431\u0435\u0441\u043f\u043b\u0430\u0442\u043d\u044b\u0439 \u043f\u0440\u043e\u0431\u043d\u044b\u0439 \u043f\u0435\u0440\u0438\u043e\u0434, \u043e\u043f\u043b\u0430\u0442\u0430 \u043d\u0430\u0447\u043d\u0451\u0442\u0441\u044f \u043f\u043e\u0441\u043b\u0435 \u043d\u0435\u0433\u043e, \u0435\u0441\u043b\u0438 \u043d\u0435 \u043e\u0442\u043c\u0435\u043d\u0438\u0442\u044c \u043f\u043e\u0434\u043f\u0438\u0441\u043a\u0443 \u0434\u043e \u0435\u0433\u043e \u043e\u043a\u043e\u043d\u0447\u0430\u043d\u0438\u044f. \u0412\u043e\u0437\u0432\u0440\u0430\u0442\u044b \u2014 \u043f\u043e \u043f\u0440\u0430\u0432\u0438\u043b\u0430\u043c Google Play. \u041f\u043e\u0434\u043f\u0438\u0441\u043a\u0443 \u043c\u043e\u0436\u043d\u043e \u0432\u043e\u0441\u0441\u0442\u0430\u043d\u043e\u0432\u0438\u0442\u044c \u043d\u0430 \u0434\u0440\u0443\u0433\u043e\u043c \u0442\u0435\u043b\u0435\u0444\u043e\u043d\u0435 \u0441 \u0442\u0435\u043c \u0436\u0435 \u0430\u043a\u043a\u0430\u0443\u043d\u0442\u043e\u043c Google \u043a\u043d\u043e\u043f\u043a\u043e\u0439 \xab\u0412\u043e\u0441\u0441\u0442\u0430\u043d\u043e\u0432\u0438\u0442\u044c \u043f\u043e\u043a\u0443\u043f\u043a\u0438\xbb.\n\n7. \u041c\u044b \u043c\u043e\u0436\u0435\u043c \u043e\u0431\u043d\u043e\u0432\u043b\u044f\u0442\u044c \u043f\u0440\u0438\u043b\u043e\u0436\u0435\u043d\u0438\u0435 \u0438 \u044d\u0442\u0438 \u0443\u0441\u043b\u043e\u0432\u0438\u044f. \u0410\u043a\u0442\u0443\u0430\u043b\u044c\u043d\u0430\u044f \u0432\u0435\u0440\u0441\u0438\u044f \u0432\u0441\u0435\u0433\u0434\u0430 \u0434\u043e\u0441\u0442\u0443\u043f\u043d\u0430 \u0432 \u043f\u0440\u0438\u043b\u043e\u0436\u0435\u043d\u0438\u0438.",null)
